Simulación basada en agentes.ejemplo:
class Agente:
    def __init__(self, estado, vecinos): self.estado, self.vecinos = estado, vecinos
    def step(self):
        activos = sum(1 for v in self.vecinos if v.estado == 'I')
        if self.estado == 'S' and activos >= 2:
            self.proximo = 'I'
# En activación síncrona se aplica self.estado = self.proximo tras evaluar a todos

