def on_evento_fin_servicio(estado, fel, t):
    assert estado['ocupados'] > 0
    if estado['cola'] > 0:
        estado['cola'] -= 1
        fel.push(t + sample_service(), 'FIN_SERVICIO')
    else:
        estado['ocupados'] -= 1
